import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n >= 99:
        return 'C'
    # track opponent recent behavior
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_opp = opp[-1]
    last_me = me[-1]

    # Endgame exploitation against very cooperative opponents
    if n >= 92:
        if opp_c >= n - 3:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Detect sustained defectors
    if n >= 6:
        recent = opp[-6:]
        if recent.count('D') >= 5:
            return 'D'

    # Punish last defection but forgive quickly to preserve CC
    if last_opp == 'D':
        if last_me == 'D':
            # mutual defection: try to restart cooperation occasionally
            tail = opp[-3:]
            if len(tail) >= 3 and tail.count('D') == 3:
                return 'C' if rng.random() < 0.4 else 'D'
            return 'D'
        return 'D'

    # opponent cooperated last round
    # If opponent has been very cooperative, mainly cooperate but probe rarely
    if opp_d <= max(1, n // 8):
        if n >= 20 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Moderate defection: use tit-for-tat with forgiveness and 2-strike retaliation
    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'
    if n >= 5 and opp[-5:].count('D') >= 3:
        return 'D'
    return 'C'
